#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: This script runs Terraform init and validate offline.\n# It then runs plan and greps for expected resources.\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\nMODULE_DIR="${SCRIPT_DIR}/.."\n\ncd "$MODULE_DIR"\n\nterraform init -backend=false > /dev/null\n\nterraform validate\n\nPLAN_OUTPUT=$(terraform plan -no-color)\n\n# Check that the bucket resource is present\necho "$PLAN_OUTPUT" | grep -q 'aws_s3_bucket.safehouse'\n\n# Check that versioning is enabled\necho "$PLAN_OUTPUT" | grep -q 'aws_s3_bucket_versioning.safehouse'\n\n# Check that encryption is configured\necho "$PLAN_OUTPUT" | grep -q 'aws_s3_bucket_server_side_encryption_configuration.safehouse'\n\n# Check that lifecycle rule exists\necho "$PLAN_OUTPUT" | grep -q 'aws_s3_bucket_lifecycle_configuration.safehouse'\n\necho "All checks passed."
